+        margin: 0;
+        font-size: clamp(2rem, 8vw, 3rem);
+        line-height: 1;
+      }
+
+      .intro {
+        margin: 1rem 0 1.75rem;
+        color: var(--muted);
+      }
+
+      form {
+        display: grid;
+        gap: 1.25rem;
+      }
+
+      .form-field {
+        display: grid;
+        gap: 0.65rem;
+        border: 1px solid rgba(186, 196, 209, 0.18);
+        border-radius: 1rem;
+        background: rgba(8, 11, 18, 0.55);
+        padding: 1rem;
+      }
+
+      .checkbox-row {
+        display: grid;
+        grid-template-columns: auto 1fr;
+        gap: 0.8rem;
+        align-items: start;
+      }
+
+      input[type="checkbox"] {
+        width: 1.3rem;
+        height: 1.3rem;
+        margin: 0.15rem 0 0;
+        accent-color: var(--accent);
+        cursor: pointer;
+      }
+
+      label {
+        color: var(--text);
+        font-weight: 700;
+        cursor: pointer;
+      }
+
+      .required {
+        color: var(--accent-strong);
+        font-weight: 800;
+      }
+
+      .helper,
+      .error,
+      .status {
+        margin: 0;
+        font-size: 0.95rem;
+      }
+
+      .helper {
+        color: var(--muted);
+      }
+
+      .error {
+        color: var(--error);
+        font-weight: 700;
+      }
+
+      .status {
+        color: #c4b5fd;
+      }
+
+      [hidden] {
+        display: none;
+      }
+
+      button {
+        min-height: 2.9rem;
+        border: 0;
+        border-radius: 999px;
+        background: linear-gradient(135deg, var(--accent), #06b6d4);
+        color: #ffffff;
+        cursor: pointer;
+        font: inherit;
+        font-weight: 800;
+        letter-spacing: 0.01em;
+        padding: 0.85rem 1.25rem;
+      }
+
+      button:hover {
+        filter: brightness(1.08);
+      }
+
+      a {
+        color: #c4b5fd;
+        text-underline-offset: 0.18em;
+      }
+
+      a:hover {
+        color: #ddd6fe;
+      }
+
+      :focus-visible {
+        outline: 3px solid #fde68a;
+        outline-offset: 4px;
+      }
+
+      @media (forced-colors: active) {
+        .consent-card,
+        .form-field,
+        button,
+        .skip-link {
+          border: 1px solid CanvasText;
+        }
+
+        button {
+          background: ButtonFace;
+          color: ButtonText;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <a class="skip-link" href="#main-content">Skip to main content</a>
+    <main id="main-content">
+      <div id="root"></div>
+    </main>
+
+    <script>
+      const formState = {
+        agreed: false,
+        submitted: false
+      };
+
+      function ConsentCheckbox({ agreed, submitted }) {
+        const showError = submitted && !agreed;
+        const describedBy = showError ? "terms-helper terms-error" : "terms-helper";
+
+        return `
+          <div class="form-field">
+            <div class="checkbox-row">
+              <input
+                id="agree-terms"
+                name="agreeTerms"
+                type="checkbox"
+                required
+                ${agreed ? "checked" : ""}
+                aria-describedby="${describedBy}"
+                aria-invalid="${showError ? "true" : "false"}"
+              >
+              <label for="agree-terms">
+                I agree to the <a href="#" aria-label="terms of use">terms of use</a>
+                <span class="required" aria-hidden="true">*</span>
+                <span class="sr-required">required</span>
+              </label>
+            </div>
+            <p id="terms-helper" class="helper">Required to create and manage your account.</p>
+            <p id="terms-error" class="error" ${showError ? "" : "hidden"}>Error: Agree to the terms of use before continuing.</p>
+          </div>
+        `;
+      }
+
+      function ConsentForm(state) {
+        return `
+          <section class="consent-card" aria-labelledby="form-title">
+            <p class="eyebrow">Consent required</p>
+            <h1 id="form-title">Review the terms</h1>
+            <p class="intro">Confirm your agreement before submitting this short form.</p>
+            <form novalidate>
+              ${ConsentCheckbox(state)}
+              <button type="submit">Agree and continue</button>
+              <p id="form-status" class="status" aria-live="polite"></p>
+            </form>
+          </section>
+        `;
+      }
+
+      function render() {
+        document.getElementById("root").innerHTML = ConsentForm(formState);
+        bindFormEvents();
+      }
+
+      function bindFormEvents() {
+        const form = document.querySelector("form");
+        const checkbox = document.getElementById("agree-terms");
+        const status = document.getElementById("form-status");
+
+        checkbox.addEventListener("change", () => {
+          formState.agreed = checkbox.checked;
+          formState.submitted = false;
+          render();
+        });
+
+        form.addEventListener("submit", (event) => {
+          event.preventDefault();
+          formState.agreed = checkbox.checked;
+          formState.submitted = true;
+
+          if (!checkbox.checked) {
+            render();
+            document.getElementById("agree-terms").focus();
+            return;
+          }
+
+          status.textContent = "Thanks. Your agreement has been recorded.";
+        });
+      }
+
+      render();
+    </script>
+  </body>
+</html>
*** End Patch
