<html lang="en">
  <head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Terms Consent Form</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #080b12;
        --card: #111827;
        --card-border: #2a3446;
        --text: #f8fafc;
        --muted: #bac4d1;
        --accent: #8b5cf6;
        --accent-strong: #a78bfa;
        --error: #fca5a5;
        --shadow: 0 24px 70px rgba(0, 0, 0, 0.45);
      }

      * {
        box-sizing: border-box;
      }

      body {
        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(139, 92, 246, 0.24), transparent 34rem),
          radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.16), transparent 30rem),
          var(--bg);
        line-height: 1.5;
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        background: var(--text);
        color: var(--bg);
        padding: 0.65rem 1rem;
        font-weight: 700;
        text-decoration: none;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      main {
        display: grid;
        min-height: 100vh;
        place-items: center;
        padding: 2rem 1rem;
      }

      .consent-card {
        width: min(100%, 31rem);
        border: 1px solid var(--card-border);
        border-radius: 1.5rem;
        background: linear-gradient(145deg, rgba(17, 24, 39, 0.96), rgba(15, 23, 42, 0.9));
        box-shadow: var(--shadow);
        padding: clamp(1.5rem, 4vw, 2.5rem);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--accent-strong);
        font-size: 0.85rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 8vw, 3rem);
        line-height: 1;
      }

      .intro {
        margin: 1rem 0 1.75rem;
        color: var(--muted);
      }

      form {
        display: grid;
        gap: 1.25rem;
      }

      .form-field {
        display: grid;
        gap: 0.65rem;
        border: 1px solid rgba(186, 196, 209, 0.18);
        border-radius: 1rem;
        background: rgba(8, 11, 18, 0.55);
        padding: 1rem;
      }

      .checkbox-row {
        display: grid;
        grid-template-columns: auto 1fr;
        gap: 0.8rem;
        align-items: start;
      }

      input[type="checkbox"] {
        width: 1.3rem;
        height: 1.3rem;
        margin: 0.15rem 0 0;
        accent-color: var(--accent);
        cursor: pointer;
      }

      label {
        color: var(--text);
        font-weight: 700;
        cursor: pointer;
      }

      .required {
        color: var(--accent-strong);
        font-weight: 800;
      }

      .helper,
      .error,
      .status {
        margin: 0;
        font-size: 0.95rem;
      }

      .helper {
        color: var(--muted);
      }

      .error {
        color: var(--error);
        font-weight: 700;
      }

      .status {
        color: #c4b5fd;
      }

      [hidden] {
        display: none;
      }

      button {
        min-height: 2.9rem;
        border: 0;
        border-radius: 999px;
        background: linear-gradient(135deg, var(--accent), #06b6d4);
        color: #ffffff;
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        letter-spacing: 0.01em;
        padding: 0.85rem 1.25rem;
      }

      button:hover {
        filter: brightness(1.08);
      }

      a {
        color: #c4b5fd;
        text-underline-offset: 0.18em;
      }

      a:hover {
        color: #ddd6fe;
      }

      :focus-visible {
        outline: 3px solid #fde68a;
        outline-offset: 4px;
      }

      @media (forced-colors: active) {
        .consent-card,
        .form-field,
        button,
        .skip-link {
          border: 1px solid CanvasText;
        }

        button {
          background: ButtonFace;
          color: ButtonText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content">
      <div id="root"></div>
    </main>

    <script>
      const formState = {
        agreed: false,
        submitted: false
      };

      function ConsentCheckbox({ agreed, submitted }) {
        const showError = submitted && !agreed;
        const describedBy = showError ? "terms-helper terms-error" : "terms-helper";

        return `
          <div class="form-field">
            <div class="checkbox-row">
              <input
                id="agree-terms"
                name="agreeTerms"
                type="checkbox"
                required
                ${agreed ? "checked" : ""}
                aria-describedby="${describedBy}"
                aria-invalid="${showError ? "true" : "false"}"
              >
              <label for="agree-terms">
                I agree to the <a href="#" aria-label="terms of use">terms of use</a>
                <span class="required" aria-hidden="true">*</span>
                <span class="sr-required">required</span>
              </label>
            </div>
            <p id="terms-helper" class="helper">Required to create and manage your account.</p>
            <p id="terms-error" class="error" ${showError ? "" : "hidden"}>Error: Agree to the terms of use before continuing.</p>
          </div>
        `;
      }

      function ConsentForm(state) {
        return `
          <section class="consent-card" aria-labelledby="form-title">
            <p class="eyebrow">Consent required</p>
            <h1 id="form-title">Review the terms</h1>
            <p class="intro">Confirm your agreement before submitting this short form.</p>
            <form novalidate>
              ${ConsentCheckbox(state)}
              <button type="submit">Agree and continue</button>
              <p id="form-status" class="status" aria-live="polite"></p>
            </form>
          </section>
        `;
      }

      function render() {
        document.getElementById("root").innerHTML = ConsentForm(formState);
        bindFormEvents();
      }

      function bindFormEvents() {
        const form = document.querySelector("form");
        const checkbox = document.getElementById("agree-terms");
        const status = document.getElementById("form-status");

        checkbox.addEventListener("change", () => {
          formState.agreed = checkbox.checked;
          formState.submitted = false;
          render();
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();
          formState.agreed = checkbox.checked;
          formState.submitted = true;

          if (!checkbox.checked) {
            render();
            document.getElementById("agree-terms").focus();
            return;
          }

          status.textContent = "Thanks. Your agreement has been recorded.";
        });
      }

      render();
    </script>
  </body>
</html>
